public interface Auditable {
    String getAuditTrail();

    default void logAudit() {
        System.out.println("Auditing record: " + getAuditTrail());
        validateSecurityContext();
    }

    private void validateSecurityContext() {
        // Private interface methods (Java 9+) encapsulate helper logic
        if (Thread.currentThread().getName().contains("Unauthorized")) {
            throw new SecurityException("Access denied during audit logging");
        }
    }
}

public abstract class BaseEntity implements Auditable {
    protected Long id;
    protected boolean active;

    protected BaseEntity(Long id) {
        this.id = id;
        this.active = true;
    }

    public abstract void persist();
}
